"""Result schemas.

CALL-E validates the call outcome against a JSON Schema and returns
`structured_result` matching it, so the agent gets typed data instead of
prose. Keep schemas small and closed-ended — enums beat free text.

Two levels exist:
  result_schema            -> the task as a whole (one object per call task)
  recipient_result_schema  -> per recipient, for batch tasks
"""

from __future__ import annotations

from typing import Any

JsonSchema = dict[str, Any]

#: Sensible default when the caller does not supply a schema: did it work?
DEFAULT_RECIPIENT_SCHEMA: JsonSchema = {
    "type": "object",
    "required": ["outcome"],
    "properties": {
        "outcome": {
            "type": "string",
            "enum": ["success", "refused", "unreachable", "unknown"],
            "description": "Whether the call goal was achieved.",
        },
        "notes": {
            "type": "string",
            "description": "One sentence of context for the outcome.",
        },
    },
}

#: Batch roll-up counterpart to DEFAULT_RECIPIENT_SCHEMA.
DEFAULT_TASK_SCHEMA: JsonSchema = {
    "type": "object",
    "required": ["completed_count"],
    "properties": {
        "completed_count": {
            "type": "integer",
            "description": "Number of recipients where the goal was achieved.",
        },
    },
}


def enum_schema(field: str, options: list[str], *, description: str = "") -> JsonSchema:
    """Build a one-field enum schema — the most reliable shape for CALL-E.

    >>> enum_schema("can_attend", ["yes", "no", "unknown"])["required"]
    ['can_attend']
    """
    if not options:
        raise ValueError("enum_schema requires at least one option.")
    prop: JsonSchema = {"type": "string", "enum": options}
    if description:
        prop["description"] = description
    return {"type": "object", "required": [field], "properties": {field: prop}}
