"""Placing calls through CALL-E and normalising the results.

Lifecycle: create -> (queued/in progress) -> completed | failed | canceled.
Either poll with wait_for_result, or pass webhook_url and let CALL-E push
the terminal payload to the receiver in calling_agent.webhook.
"""

from __future__ import annotations

import re
import uuid
from dataclasses import dataclass, field
from typing import Any

from calle import CalleClient

from calling_agent.config import Settings, load_settings
from calling_agent.schemas import JsonSchema

#: E.164: leading +, country digit 1-9, 7-14 more digits.
E164 = re.compile(r"^\+[1-9]\d{7,14}$")

TERMINAL_STATUSES = frozenset({"completed", "failed", "canceled"})


class InvalidPhoneNumber(ValueError):
    """Phone number is not valid E.164."""


class RealCallBlocked(RuntimeError):
    """A real call was attempted while the safety guard is engaged."""


@dataclass(frozen=True)
class Transcript:
    speaker: str
    text: str
    offset_seconds: float | None = None

    def __str__(self) -> str:
        stamp = "" if self.offset_seconds is None else f"[{self.offset_seconds:>5.1f}s] "
        return f"{stamp}{self.speaker}: {self.text}"


@dataclass(frozen=True)
class CallOutcome:
    """Flat view of a terminal CALL-E call payload."""

    id: str
    status: str
    task_completed: bool | None = None
    confidence_score: float | None = None
    confidence_label: str | None = None
    structured_result: dict[str, Any] = field(default_factory=dict)
    evidence: list[str] = field(default_factory=list)
    transcript: list[Transcript] = field(default_factory=list)
    raw: dict[str, Any] = field(default_factory=dict)

    @property
    def is_terminal(self) -> bool:
        return self.status in TERMINAL_STATUSES

    @property
    def succeeded(self) -> bool:
        return self.status == "completed" and bool(self.task_completed)

    @classmethod
    def from_payload(cls, payload: dict[str, Any]) -> "CallOutcome":
        """Build from an API payload, tolerating fields the API omits."""
        confidence = payload.get("completion_confidence") or {}
        if not isinstance(confidence, dict):
            confidence = {}
        return cls(
            id=str(payload.get("id") or payload.get("call_id") or ""),
            status=str(payload.get("status") or "unknown"),
            task_completed=payload.get("task_completed"),
            confidence_score=confidence.get("score"),
            confidence_label=confidence.get("label"),
            structured_result=payload.get("structured_result") or {},
            evidence=list(payload.get("evidence") or []),
            transcript=_extract_transcript(payload),
            raw=payload,
        )


def _extract_transcript(payload: dict[str, Any]) -> list[Transcript]:
    """Flatten recipients[].attempts[].transcript_turns[] into one list."""
    turns: list[Transcript] = []
    for recipient in payload.get("recipients") or []:
        if not isinstance(recipient, dict):
            continue
        for attempt in recipient.get("attempts") or []:
            if not isinstance(attempt, dict):
                continue
            for turn in attempt.get("transcript_turns") or []:
                if not isinstance(turn, dict):
                    continue
                turns.append(
                    Transcript(
                        speaker=str(turn.get("speaker") or "unknown"),
                        text=str(turn.get("text") or ""),
                        offset_seconds=turn.get("offset_seconds"),
                    )
                )
    return turns


def normalize_phone(phone: str) -> str:
    """Strip spaces/dashes and require E.164."""
    cleaned = re.sub(r"[\s\-()]", "", phone or "")
    if not E164.match(cleaned):
        raise InvalidPhoneNumber(
            f"{phone!r} is not E.164. Use the full international form, e.g. +4915112345678."
        )
    return cleaned


def assert_call_allowed(phone: str, settings: Settings) -> None:
    """Guard real dialing behind CALLE_ALLOW_REAL_CALLS and the allowlist."""
    if not settings.allow_real_calls:
        raise RealCallBlocked(
            "Real calls are disabled. Set CALLE_ALLOW_REAL_CALLS=1 to arm dialing "
            "(each call is billable)."
        )
    if settings.allowed_numbers and phone not in settings.allowed_numbers:
        raise RealCallBlocked(
            f"{phone} is not in CALLE_ALLOWED_NUMBERS. Add it or clear the allowlist."
        )


def build_recipient(
    phone: str,
    *,
    settings: Settings,
    region: str | None = None,
    locale: str | None = None,
    variables: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Recipient object for the CALL-E API (the SDK expands `phone` to `phones`)."""
    recipient: dict[str, Any] = {
        "phone": normalize_phone(phone),
        "region": region or settings.default_region,
        "locale": locale or settings.default_locale,
    }
    if variables:
        recipient["variables"] = variables
    return recipient


def place_call(
    client: CalleClient,
    *,
    task: str,
    phone: str,
    settings: Settings | None = None,
    result_schema: JsonSchema | None = None,
    region: str | None = None,
    locale: str | None = None,
    metadata: dict[str, Any] | None = None,
    idempotency_key: str | None = None,
    use_webhook: bool = True,
    wait: bool = False,
    interval_seconds: float = 5.0,
    timeout_seconds: float = 600.0,
) -> CallOutcome:
    """Place one outbound call.

    wait=False returns as soon as CALL-E accepts the task — the usual choice
    for an agent, which then reacts to the webhook or polls later.
    wait=True blocks until terminal; convenient for scripts and demos.
    """
    settings = settings or load_settings()
    if not task.strip():
        raise ValueError("task must describe the call goal.")

    recipient = build_recipient(
        phone, settings=settings, region=region, locale=locale
    )
    assert_call_allowed(recipient["phone"], settings)

    webhook_url = settings.webhook_url if use_webhook else None

    payload = client.calls.create(
        task=task,
        recipient=recipient,
        result_schema=result_schema,
        metadata=metadata,
        webhook_url=webhook_url,
        # Retrying without a key would place a second real call.
        idempotency_key=idempotency_key or f"agent-{uuid.uuid4()}",
    )

    if not wait:
        return CallOutcome.from_payload(payload)

    final = client.calls.wait_for_result(
        str(payload["id"]),
        interval_seconds=interval_seconds,
        timeout_seconds=timeout_seconds,
    )
    return CallOutcome.from_payload(final)


def get_call(client: CalleClient, call_id: str) -> CallOutcome:
    """Read the current state of a call."""
    return CallOutcome.from_payload(client.calls.get(call_id))
