<body>
<header>
  <h1>Machining Quote</h1>
  <span class="flow">STEP → time → cost → ERP purchase history</span>
</header>

<div class="layout">
  <aside>
    <div class="card">
      <h2>Part</h2>
      <div id="drop">
        <div class="big" id="dropTitle">Drop a STEP file</div>
        <div class="small" id="dropSub">or click to browse · .step / .stp</div>
      </div>
      <input type="file" id="file" accept=".step,.stp,.STEP,.STP" class="hide">

      <label for="material">Material</label>
      <select id="material"></select>

      <label for="quantity">Batch quantity</label>
      <input type="number" id="quantity" value="25" min="1" max="100000">

      <button class="primary" id="go" disabled>Estimate cost</button>
      <p class="muted" id="hint" style="margin:10px 0 0">
        Geometry is read with an OpenCASCADE kernel — exact volume, area and hole
        detection, not a mesh approximation.
      </p>
    </div>
  </aside>

  <main>
    <div id="error" class="err hide"></div>

    <div id="empty" class="card">
      <h2>How this works</h2>
      <p class="muted" style="margin:0 0 10px">
        Upload a solid STEP part and pick its material. The pipeline reads the real
        B-rep geometry, estimates 3-axis machining time from removal volume, surface
        area and detected holes, prices it at shop rates, then benchmarks the result
        in €/kg against what the ERP has actually paid for parts in the same material
        group.
      </p>
      <p class="muted" style="margin:0">
        Where an estimate lands far from the purchase history, the calling agent can
        phone the supplier about it — CALL-E places the call and returns a structured
        answer.
      </p>
    </div>

    <div id="results" class="hide">
      <div class="tiles">
        <div class="tile"><div class="k">Unit price</div><div class="v" id="tPrice">—</div><div class="s" id="tTotal"></div></div>
        <div class="tile"><div class="k">Cycle time</div><div class="v" id="tTime">—</div><div class="s" id="tSetups"></div></div>
        <div class="tile"><div class="k">Part mass</div><div class="v" id="tMass">—</div><div class="s" id="tStock"></div></div>
        <div class="tile"><div class="k">vs ERP history</div><div class="v" id="tDev">—</div><div class="s" id="tMedian"></div></div>
      </div>

      <div class="grid2">
        <div class="card">
          <h2>Geometry read from STEP</h2>
          <dl class="spec" id="specList"></dl>
          <div id="holeBlock" style="margin-top:14px"></div>
        </div>

        <div class="card">
          <h2>Machining time</h2>
          <div class="bar" id="timeBar"></div>
          <div class="legend" id="timeLegend"></div>
          <table id="timeTable"></table>
        </div>
      </div>

      <div class="card">
        <h2>Cost breakdown</h2>
        <div id="costLines"></div>
      </div>

      <div class="card" id="benchCard">
        <h2>ERP purchase history — <span id="benchGroup"></span></h2>
        <div class="verdict" id="benchVerdict"></div>
        <div class="strip" id="benchStrip"></div>
        <ul class="notes" id="benchNotes"></ul>
        <h2 style="margin-top:20px">Comparable purchase lines</h2>
        <table id="benchTable"></table>
      </div>

      <div class="card hide" id="warnCard">
        <h2>Flags</h2>
        <ul class="warn-list" id="warnList"></ul>
      </div>

      <div class="card">
        <h2>Call the supplier about this quote</h2>
        <p class="muted" style="margin:0 0 12px" id="callIntro"></p>
        <div class="callrow">
          <div>
            <label for="callPhone">Supplier phone (E.164)</label>
            <input type="text" id="callPhone" placeholder="+4915112345678">
          </div>
          <div>
            <label for="callRef">ERP reference</label>
            <input type="text" id="callRef" placeholder="RFQ-4711">
          </div>
          <div style="flex:0 0 auto">
            <button class="ghost" id="callGo">Place call via CALL-E</button>
          </div>
        </div>
        <div id="callOut" class="muted" style="margin-top:12px"></div>
      </div>
    </div>
  </main>
</div>

<script>
const $ = (id) => document.getElementById(id);
const eur = (v) => '€' + v.toLocaleString('en-GB', {minimumFractionDigits: 2, maximumFractionDigits: 2});
const num = (v, d = 1) => Number(v).toLocaleString('en-GB', {minimumFractionDigits: d, maximumFractionDigits: d});
let selectedFile = null;
let lastQuote = null;

// ---- material picker -------------------------------------------------
fetch('/api/materials').then(r => r.json()).then(data => {
  const byGroup = {};
  for (const m of data.materials) (byGroup[m.material_group_name] ||= []).push(m);
  const sel = $('material');
  for (const [groupName, items] of Object.entries(byGroup)) {
    const og = document.createElement('optgroup');
    og.label = groupName;
    for (const m of items) {
      const opt = document.createElement('option');
      opt.value = m.key;
      opt.textContent = `${m.designation} · €${m.stock_price_eur_per_kg.toFixed(2)}/kg`;
      og.appendChild(opt);
    }
    sel.appendChild(og);
  }
  sel.value = 'AW-6082';
}).catch(() => showError('Could not load material master data.'));

// ---- file selection --------------------------------------------------
const drop = $('drop');
drop.addEventListener('click', () => $('file').click());
drop.addEventListener('dragover', (e) => { e.preventDefault(); drop.classList.add('over'); });
drop.addEventListener('dragleave', () => drop.classList.remove('over'));
drop.addEventListener('drop', (e) => {
  e.preventDefault(); drop.classList.remove('over');
  if (e.dataTransfer.files.length) takeFile(e.dataTransfer.files[0]);
});
$('file').addEventListener('change', (e) => { if (e.target.files.length) takeFile(e.target.files[0]); });

function takeFile(file) {
  if (!/\.(step|stp)$/i.test(file.name)) { showError('That is not a STEP file. Use .step or .stp.'); return; }
  selectedFile = file;
  drop.classList.add('has-file');
  $('dropTitle').textContent = file.name;
  $('dropSub').textContent = (file.size / 1024).toFixed(0) + ' kB · click to replace';
  $('go').disabled = false;
  hideError();
}

function showError(msg) { $('error').textContent = msg; $('error').classList.remove('hide'); }
function hideError() { $('error').classList.add('hide'); }

// ---- run the pipeline ------------------------------------------------
$('go').addEventListener('click', async () => {
  if (!selectedFile) return;
  const btn = $('go');
  btn.disabled = true;
  btn.innerHTML = '<span class="spinner"></span>Reading geometry…';
  hideError();

  const body = new FormData();
  body.append('step_file', selectedFile);
  body.append('material', $('material').value);
  body.append('quantity', $('quantity').value);

  try {
    const res = await fetch('/api/quote', {method: 'POST', body});
    const data = await res.json();
    if (!res.ok) throw new Error(data.detail || 'Quoting failed.');
    lastQuote = data;
    render(data);
  } catch (err) {
    showError(err.message);
    $('results').classList.add('hide');
    $('empty').classList.remove('hide');
  } finally {
    btn.disabled = false;
    btn.textContent = 'Estimate cost';
  }
});

// ---- rendering -------------------------------------------------------
const TIME_COLOURS = {
  roughing: '#1f6feb', finishing: '#3fb27f', drilling: '#e0a04a',
  non_productive: '#8b95a3', tool_changes: '#b06fd0'
};
const TIME_LABELS = {
  roughing: 'Roughing', finishing: 'Finishing', drilling: 'Drilling',
  non_productive: 'Non-productive', tool_changes: 'Tool changes'
};

function render(d) {
  $('empty').classList.add('hide');
  $('results').classList.remove('hide');

  // tiles
  $('tPrice').textContent = eur(d.cost.unit_price_eur);
  $('tTotal').textContent = `${eur(d.cost.total_price_eur)} for ${d.cost.quantity} off · ${eur(d.cost.eur_per_kg)}/kg`;
  $('tTime').textContent = num(d.machining.cycle_minutes, 1) + ' min';
  $('tSetups').textContent = `${d.machining.setups} setup${d.machining.setups > 1 ? 's' : ''} · ${num(d.machining.minutes_per_part, 1)} min/part incl. batch`;
  $('tMass').textContent = num(d.part.part_mass_kg, 3) + ' kg';
  $('tStock').textContent = `from ${num(d.machining.stock_mass_kg, 3)} kg stock · ${(d.part.solidity * 100).toFixed(0)}% retained`;

  if (d.benchmark) {
    const dev = d.benchmark.deviation_pct;
    $('tDev').textContent = (dev >= 0 ? '+' : '') + dev.toFixed(0) + '%';
    $('tDev').style.color = d.benchmark.verdict === 'in_line' ? 'var(--ok)'
                          : d.benchmark.verdict === 'above' ? 'var(--bad)' : 'var(--warn)';
    $('tMedian').textContent = `median ${eur(d.benchmark.median_eur_per_kg)}/kg · n=${d.benchmark.sample_size}`;
  } else {
    $('tDev').textContent = '—';
    $('tMedian').textContent = 'no purchase history';
  }

  // geometry
  const p = d.part, bb = p.bounding_box_mm;
  $('specList').innerHTML = [
    ['Source', p.source_name],
    ['Bounding box', `${num(bb[0])} × ${num(bb[1])} × ${num(bb[2])} mm`],
    ['Stock envelope', d.machining.stock_mm.map(v => num(v)).join(' × ') + ' mm'],
    ['Part volume', num(p.volume_mm3, 0) + ' mm³'],
    ['Removed volume', num(d.machining.removed_volume_mm3, 0) + ' mm³'],
    ['Surface area', num(p.surface_area_mm2, 0) + ' mm²'],
    ['Solidity', (p.solidity * 100).toFixed(1) + '%'],
    ['Faces', `${p.planar_faces} planar · ${p.curved_faces} curved`],
    ['Solid bodies', p.solids],
    ['Material', d.material.designation],
  ].map(([k, v]) => `<dt>${k}</dt><dd>${v}</dd>`).join('');

  if (p.holes.length) {
    const byKind = {};
    for (const h of p.holes) {
      const key = `Ø${h.diameter_mm.toFixed(1)} × ${h.depth_mm.toFixed(1)} mm ${h.through ? 'through' : 'blind'} (${h.axis})`;
      byKind[key] = (byKind[key] || 0) + 1;
    }
    $('holeBlock').innerHTML = `<h2>Detected holes (${p.holes.length})</h2>` +
      Object.entries(byKind).map(([k, n]) => `<div style="font-size:12.5px;padding:2px 0">
        <span class="pill">${n}×</span> ${k}</div>`).join('');
  } else {
    $('holeBlock').innerHTML = `<h2>Detected holes</h2><p class="muted" style="margin:0">
      No drilled holes found. External rounds and fillets are excluded by design.</p>`;
  }

  // time
  const bd = d.machining.breakdown_minutes;
  const cycleKeys = ['roughing', 'finishing', 'drilling', 'non_productive', 'tool_changes'];
  const total = cycleKeys.reduce((s, k) => s + bd[k], 0) || 1;
  $('timeBar').innerHTML = cycleKeys.map(k =>
    `<span style="width:${(bd[k] / total * 100).toFixed(2)}%;background:${TIME_COLOURS[k]}" title="${TIME_LABELS[k]}"></span>`).join('');
  $('timeLegend').innerHTML = cycleKeys.map(k =>
    `<span><i style="background:${TIME_COLOURS[k]}"></i>${TIME_LABELS[k]}</span>`).join('');
  $('timeTable').innerHTML =
    '<tr><th>Operation</th><th class="num">Minutes</th><th class="num">Share</th></tr>' +
    cycleKeys.map(k => `<tr><td>${TIME_LABELS[k]}</td><td class="num">${num(bd[k], 2)}</td>
      <td class="num">${(bd[k] / total * 100).toFixed(0)}%</td></tr>`).join('') +
    `<tr><td><strong>Cycle per part</strong></td><td class="num"><strong>${num(d.machining.cycle_minutes, 2)}</strong></td><td class="num"></td></tr>` +
    `<tr><td>Setup (per batch)</td><td class="num">${num(bd.setup_per_batch, 0)}</td><td class="num muted">÷ ${d.cost.quantity}</td></tr>` +
    `<tr><td>Programming (per batch)</td><td class="num">${num(bd.programming_per_batch, 0)}</td><td class="num muted">÷ ${d.cost.quantity}</td></tr>`;

  // cost
  const maxAbs = Math.max(...d.cost.lines.map(l => Math.abs(l.eur)));
  $('costLines').innerHTML = d.cost.lines.map(l => {
    const credit = l.eur < 0;
    return `<div class="costline">
      <span>${l.label}</span>
      <span class="track"><span class="fill ${credit ? 'credit' : ''}" style="width:${(Math.abs(l.eur) / maxAbs * 100).toFixed(1)}%"></span></span>
      <span class="amt">${credit ? '−' : ''}${eur(Math.abs(l.eur))}</span>
    </div>`;
  }).join('') + `<div class="costline total">
      <span>Unit price</span><span></span><span class="amt">${eur(d.cost.unit_price_eur)}</span></div>`;

  // benchmark
  if (d.benchmark) {
    $('benchCard').classList.remove('hide');
    const b = d.benchmark;
    $('benchGroup').textContent = `${b.material_group_name} (${b.material_group})`;
    $('benchVerdict').className = 'verdict ' + b.verdict;
    $('benchVerdict').textContent = b.headline +
      ` At the group median this part would be ${eur(b.implied_price_at_median_eur)}.`;
    renderStrip(b);
    $('benchNotes').innerHTML = b.notes.map(n => `<li>${n}</li>`).join('') +
      `<li>Estimate sits at the ${b.percentile.toFixed(0)}th percentile of ${b.sample_size} purchase line(s).</li>`;
    $('benchTable').innerHTML =
      '<tr><th>Date</th><th>Part</th><th>Description</th><th>Supplier</th><th class="num">kg</th><th class="num">€/unit</th><th class="num">€/kg</th></tr>' +
      b.comparable_lines.map(l => `<tr>
        <td>${l.order_date}</td><td>${l.part_number}</td><td>${l.description}</td>
        <td>${l.supplier}</td><td class="num">${num(l.unit_weight_kg, 3)}</td>
        <td class="num">${num(l.unit_price_eur, 2)}</td><td class="num">${num(l.eur_per_kg, 2)}</td></tr>`).join('');
  } else {
    $('benchCard').classList.add('hide');
  }

  // flags
  if (d.warnings.length) {
    $('warnCard').classList.remove('hide');
    $('warnList').innerHTML = d.warnings.map(w => `<li>${w}</li>`).join('');
  } else {
    $('warnCard').classList.add('hide');
  }

  // call panel
  const dev = d.benchmark ? d.benchmark.deviation_pct : 0;
  $('callIntro').textContent = d.benchmark && d.benchmark.verdict === 'above'
    ? `This quote is ${dev.toFixed(0)}% above the ${d.benchmark.material_group_name} history. CALL-E can phone a supplier and ask them to price it.`
    : 'CALL-E places the call, holds the conversation, and returns a structured answer against the ERP reference.';
  $('callRef').value = 'RFQ-' + (p.source_name || 'part').replace(/\.(step|stp)$/i, '').toUpperCase().slice(0, 12);
}

function renderStrip(b) {
  const lo = Math.min(b.min_eur_per_kg, b.estimate_eur_per_kg);
  const hi = Math.max(b.max_eur_per_kg, b.estimate_eur_per_kg);
  const span = (hi - lo) || 1;
  const at = (v) => ((v - lo) / span * 100);
  const clamp = (v) => Math.max(0, Math.min(100, v));

  $('benchStrip').innerHTML = `
    <div class="axis"></div>
    <div class="iqr" style="left:${clamp(at(b.p25_eur_per_kg))}%;width:${clamp(at(b.p75_eur_per_kg) - at(b.p25_eur_per_kg))}%"></div>
    <div class="median" style="left:${clamp(at(b.median_eur_per_kg))}%"></div>
    <div class="mark" style="left:${clamp(at(b.estimate_eur_per_kg))}%"></div>
    <div class="lab below" style="left:0">${eur(b.min_eur_per_kg)}/kg</div>
    <div class="lab below" style="right:0">${eur(b.max_eur_per_kg)}/kg</div>
    <div class="lab med" style="left:${clamp(at(b.median_eur_per_kg))}%;transform:translateX(-50%)">median ${eur(b.median_eur_per_kg)}</div>
    <div class="lab above" style="left:${clamp(at(b.estimate_eur_per_kg))}%;transform:translateX(-50%);top:52px">this quote ${eur(b.estimate_eur_per_kg)}</div>`;
}

// ---- calling agent ---------------------------------------------------
$('callGo').addEventListener('click', async () => {
  if (!lastQuote) return;
  const phone = $('callPhone').value.trim();
  const ref = $('callRef').value.trim();
  const out = $('callOut');
  if (!phone || !ref) { out.textContent = 'Phone number and ERP reference are both required.'; return; }

  const d = lastQuote;
  const task = `You are calling about a machined part enquiry, reference ${ref}. ` +
    `The part is ${d.part.source_name}, made from ${d.material.designation}, ` +
    `weighing ${num(d.part.part_mass_kg, 2)} kg, in a batch of ${d.cost.quantity}. ` +
    `Ask whether they can quote it at or below ${eur(d.cost.unit_price_eur)} per piece, ` +
    `and what lead time they would offer.`;

  const btn = $('callGo');
  btn.disabled = true;
  btn.innerHTML = '<span class="spinner"></span>Placing…';
  try {
    const res = await fetch('/calls', {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({task, phone, erp_reference: ref,
        expect: ['yes', 'no', 'unknown'], expect_field: 'can_meet_price',
        metadata: {unit_price_eur: d.cost.unit_price_eur, material_group: d.material.material_group}})
    });
    const data = await res.json();
    if (!res.ok) throw new Error(data.detail || 'Call could not be placed.');
    out.innerHTML = `Call <span class="pill">${data.call_id}</span> accepted (${data.status}) for ${data.erp_reference}. ` +
      `The result arrives at the ERP callback when the call ends.`;
  } catch (err) {
    out.textContent = err.message;
  } finally {
    btn.disabled = false;
    btn.textContent = 'Place call via CALL-E';
  }
});
</script>
</body>
</html>
