// Flat-shaded B-rep viewer with per-face colouring and click picking.
// WebGL2, no dependencies. Faces are coloured from a lookup texture so the
// heatmap can change every frame without touching the vertex buffers.

const VERT = `#version 300 es
precision highp float;
in vec3 aPos;
in float aFace;
uniform mat4 uProj, uView;
out vec3 vWorld;
flat out int vFace;
void main() {
  vWorld = aPos;
  vFace = int(aFace);
  gl_Position = uProj * uView * vec4(aPos, 1.0);
}`;

const FRAG = `#version 300 es
precision highp float;
in vec3 vWorld;
flat in int vFace;
uniform sampler2D uFaceColor;
uniform int uSelected;
uniform vec3 uEye;
out vec4 outColor;
void main() {
  // Flat shading straight from screen-space derivatives: no normal buffer.
  vec3 n = normalize(cross(dFdx(vWorld), dFdy(vWorld)));
  vec3 v = normalize(uEye - vWorld);
  if (dot(n, v) < 0.0) n = -n;

  vec3 base = texelFetch(uFaceColor, ivec2(vFace, 0), 0).rgb;
  vec3 key = normalize(vec3(0.5, 0.8, 1.0));
  float lambert = max(dot(n, key), 0.0);
  float fill = max(dot(n, normalize(vec3(-0.6, -0.3, 0.4))), 0.0);
  float rim = pow(1.0 - max(dot(n, v), 0.0), 2.5);

  vec3 lit = base * (0.34 + 0.62 * lambert + 0.16 * fill) + rim * 0.20;
  if (vFace == uSelected) lit = mix(lit, vec3(1.0, 1.0, 1.0), 0.42);
  outColor = vec4(pow(lit, vec3(0.4545)), 1.0);
}`;

const PICK_FRAG = `#version 300 es
precision highp float;
flat in int vFace;
out vec4 outColor;
void main() {
  int id = vFace + 1;             // 0 is reserved for "nothing here"
  outColor = vec4(
    float(id & 0xFF) / 255.0,
    float((id >> 8) & 0xFF) / 255.0,
    float((id >> 16) & 0xFF) / 255.0,
    1.0);
}`;

const LINE_VERT = `#version 300 es
precision highp float;
in vec3 aPos;
uniform mat4 uProj, uView;
void main() { gl_Position = uProj * uView * vec4(aPos, 1.0); }`;

const LINE_FRAG = `#version 300 es
precision highp float;
uniform vec4 uColor;
out vec4 outColor;
void main() { outColor = uColor; }`;

// ---- small matrix helpers -------------------------------------------
function perspective(fovy, aspect, near, far) {
  const f = 1 / Math.tan(fovy / 2), d = near - far;
  return [f / aspect,0,0,0, 0,f,0,0, 0,0,(far+near)/d,-1, 0,0,(2*far*near)/d,0];
}
function lookAt(eye, target, up) {
  const z = norm(sub(eye, target)), x = norm(cross(up, z)), y = cross(z, x);
  return [x[0],y[0],z[0],0, x[1],y[1],z[1],0, x[2],y[2],z[2],0,
          -dot(x,eye), -dot(y,eye), -dot(z,eye), 1];
}
const sub = (a,b) => [a[0]-b[0],a[1]-b[1],a[2]-b[2]];
const dot = (a,b) => a[0]*b[0]+a[1]*b[1]+a[2]*b[2];
const cross = (a,b) => [a[1]*b[2]-a[2]*b[1], a[2]*b[0]-a[0]*b[2], a[0]*b[1]-a[1]*b[0]];
function norm(a) { const l = Math.hypot(...a) || 1; return [a[0]/l,a[1]/l,a[2]/l]; }

function compile(gl, vertSrc, fragSrc) {
  const make = (type, src) => {
    const sh = gl.createShader(type);
    gl.shaderSource(sh, src); gl.compileShader(sh);
    if (!gl.getShaderParameter(sh, gl.COMPILE_STATUS)) {
      throw new Error('shader: ' + gl.getShaderInfoLog(sh));
    }
    return sh;
  };
  const prog = gl.createProgram();
  gl.attachShader(prog, make(gl.VERTEX_SHADER, vertSrc));
  gl.attachShader(prog, make(gl.FRAGMENT_SHADER, fragSrc));
  gl.linkProgram(prog);
  if (!gl.getProgramParameter(prog, gl.LINK_STATUS)) {
    throw new Error('link: ' + gl.getProgramInfoLog(prog));
  }
  return prog;
}

export class PartViewer {
  constructor(canvas) {
    this.canvas = canvas;
    const gl = canvas.getContext('webgl2', {antialias: true, alpha: true});
    if (!gl) throw new Error('WebGL2 is not available in this browser.');
    this.gl = gl;
    gl.enable(gl.DEPTH_TEST);
    gl.enable(gl.CULL_FACE);
    gl.cullFace(gl.BACK);

    this.prog = compile(gl, VERT, FRAG);
    this.pickProg = compile(gl, VERT, PICK_FRAG);
    this.lineProg = compile(gl, LINE_VERT, LINE_FRAG);

    this.faceCount = 0;
    this.triCount = 0;
    this.selected = -1;
    this.showStock = true;
    this.onSelect = null;

    this.yaw = -0.9; this.pitch = 0.55; this.distance = 3;
    this.target = [0, 0, 0]; this.radius = 1;

    this._initPick();
    this._bindInput();
    this._resize();
    new ResizeObserver(() => { this._resize(); this.draw(); }).observe(canvas);
  }

  // ---- geometry ------------------------------------------------------
  setMesh(mesh, faceCount, stockBox) {
    const gl = this.gl;
    const {vertices, triangles, triangle_face: triFace} = mesh;
    this.triCount = triangles.length / 3;
    this.faceCount = Math.max(faceCount, 1);

    // Expand to non-indexed triangles so every vertex carries its face id.
    const pos = new Float32Array(triangles.length * 3);
    const fid = new Float32Array(triangles.length);
    const lo = [Infinity, Infinity, Infinity], hi = [-Infinity, -Infinity, -Infinity];
    for (let t = 0; t < this.triCount; t++) {
      for (let c = 0; c < 3; c++) {
        const vi = triangles[t * 3 + c], o = (t * 3 + c) * 3;
        for (let k = 0; k < 3; k++) {
          const value = vertices[vi * 3 + k];
          pos[o + k] = value;
          if (value < lo[k]) lo[k] = value;
          if (value > hi[k]) hi[k] = value;
        }
        fid[t * 3 + c] = triFace[t];
      }
    }
    this.bounds = {lo, hi};
    this.target = [(lo[0]+hi[0])/2, (lo[1]+hi[1])/2, (lo[2]+hi[2])/2];
    this.radius = Math.max(Math.hypot(hi[0]-lo[0], hi[1]-lo[1], hi[2]-lo[2]) / 2, 1e-3);
    this.distance = this.radius * 3.0;

    this.vao = gl.createVertexArray();
    gl.bindVertexArray(this.vao);
    this._attrib(pos, 0, 3);
    this._attrib(fid, 1, 1);
    gl.bindVertexArray(null);

    this.faceColors = new Uint8Array(this.faceCount * 4).fill(200);
    this.colorTex = this.colorTex || gl.createTexture();
    this._uploadColors();
    this.setStock(stockBox);
  }

  _attrib(data, location, size) {
    const gl = this.gl;
    const buf = gl.createBuffer();
    gl.bindBuffer(gl.ARRAY_BUFFER, buf);
    gl.bufferData(gl.ARRAY_BUFFER, data, gl.STATIC_DRAW);
    gl.enableVertexAttribArray(location);
    gl.vertexAttribPointer(location, size, gl.FLOAT, false, 0, 0);
  }

  setStock(box) {
    const gl = this.gl;
    if (!box) { this.stockCount = 0; return; }
    const [x0, y0, z0, x1, y1, z1] = box;
    const c = [[x0,y0,z0],[x1,y0,z0],[x1,y1,z0],[x0,y1,z0],
               [x0,y0,z1],[x1,y0,z1],[x1,y1,z1],[x0,y1,z1]];
    const edges = [[0,1],[1,2],[2,3],[3,0],[4,5],[5,6],[6,7],[7,4],[0,4],[1,5],[2,6],[3,7]];
    const data = new Float32Array(edges.length * 6);
    edges.forEach(([a, b], i) => data.set([...c[a], ...c[b]], i * 6));
    this.stockCount = edges.length * 2;
    this.stockVao = gl.createVertexArray();
    gl.bindVertexArray(this.stockVao);
    this._attrib(data, 0, 3);
    gl.bindVertexArray(null);
  }

  // ---- colouring -----------------------------------------------------
  setFaceColors(rgbList) {
    for (let i = 0; i < this.faceCount; i++) {
      const c = rgbList[i] || [0.78, 0.78, 0.80];
      this.faceColors[i * 4 + 0] = Math.round(Math.min(1, Math.max(0, c[0])) * 255);
      this.faceColors[i * 4 + 1] = Math.round(Math.min(1, Math.max(0, c[1])) * 255);
      this.faceColors[i * 4 + 2] = Math.round(Math.min(1, Math.max(0, c[2])) * 255);
      this.faceColors[i * 4 + 3] = 255;
    }
    this._uploadColors();
  }

  _uploadColors() {
    const gl = this.gl;
    gl.bindTexture(gl.TEXTURE_2D, this.colorTex);
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, this.faceCount, 1, 0,
                  gl.RGBA, gl.UNSIGNED_BYTE, this.faceColors);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.NEAREST);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.NEAREST);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
  }

  // ---- camera + input -------------------------------------------------
  _camera() {
    const cp = Math.cos(this.pitch);
    const eye = [
      this.target[0] + this.distance * cp * Math.cos(this.yaw),
      this.target[1] + this.distance * cp * Math.sin(this.yaw),
      this.target[2] + this.distance * Math.sin(this.pitch),
    ];
    const aspect = this.canvas.width / Math.max(this.canvas.height, 1);
    return {
      eye,
      view: lookAt(eye, this.target, [0, 0, 1]),
      proj: perspective(0.72, aspect, this.radius * 0.02, this.radius * 40),
    };
  }

  _bindInput() {
    const el = this.canvas;
    let dragging = false, moved = 0, last = [0, 0];
    el.addEventListener('pointerdown', (e) => {
      dragging = true; moved = 0; last = [e.clientX, e.clientY];
      el.setPointerCapture(e.pointerId);
    });
    el.addEventListener('pointermove', (e) => {
      if (!dragging) return;
      const dx = e.clientX - last[0], dy = e.clientY - last[1];
      last = [e.clientX, e.clientY];
      moved += Math.abs(dx) + Math.abs(dy);
      this.yaw -= dx * 0.008;
      this.pitch = Math.max(-1.5, Math.min(1.5, this.pitch + dy * 0.008));
      this.draw();
    });
    el.addEventListener('pointerup', (e) => {
      dragging = false;
      el.releasePointerCapture(e.pointerId);
      if (moved < 5) this._pick(e);   // a click, not a drag
    });
    el.addEventListener('wheel', (e) => {
      e.preventDefault();
      this.distance = Math.max(this.radius * 1.15,
        Math.min(this.radius * 14, this.distance * (1 + Math.sign(e.deltaY) * 0.12)));
      this.draw();
    }, {passive: false});
  }

  resetView() {
    this.yaw = -0.9; this.pitch = 0.55; this.distance = this.radius * 3.0;
    this.draw();
  }

  // ---- picking --------------------------------------------------------
  _initPick() {
    const gl = this.gl;
    this.pickFbo = gl.createFramebuffer();
    this.pickTex = gl.createTexture();
    this.pickDepth = gl.createRenderbuffer();
  }

  _sizePick(w, h) {
    const gl = this.gl;
    gl.bindTexture(gl.TEXTURE_2D, this.pickTex);
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA8, w, h, 0, gl.RGBA, gl.UNSIGNED_BYTE, null);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.NEAREST);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.NEAREST);
    gl.bindRenderbuffer(gl.RENDERBUFFER, this.pickDepth);
    gl.renderbufferStorage(gl.RENDERBUFFER, gl.DEPTH_COMPONENT16, w, h);
    gl.bindFramebuffer(gl.FRAMEBUFFER, this.pickFbo);
    gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, this.pickTex, 0);
    gl.framebufferRenderbuffer(gl.FRAMEBUFFER, gl.DEPTH_ATTACHMENT, gl.RENDERBUFFER, this.pickDepth);
    gl.bindFramebuffer(gl.FRAMEBUFFER, null);
  }

  _pick(event) {
    if (!this.vao) return;
    const gl = this.gl;
    const rect = this.canvas.getBoundingClientRect();
    const x = Math.round((event.clientX - rect.left) * this.canvas.width / rect.width);
    const y = Math.round((rect.bottom - event.clientY) * this.canvas.height / rect.height);

    gl.bindFramebuffer(gl.FRAMEBUFFER, this.pickFbo);
    gl.viewport(0, 0, this.canvas.width, this.canvas.height);
    gl.clearColor(0, 0, 0, 1);
    gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
    const {view, proj} = this._camera();
    gl.useProgram(this.pickProg);
    gl.uniformMatrix4fv(gl.getUniformLocation(this.pickProg, 'uProj'), false, proj);
    gl.uniformMatrix4fv(gl.getUniformLocation(this.pickProg, 'uView'), false, view);
    gl.bindVertexArray(this.vao);
    gl.drawArrays(gl.TRIANGLES, 0, this.triCount * 3);

    const pixel = new Uint8Array(4);
    gl.readPixels(x, y, 1, 1, gl.RGBA, gl.UNSIGNED_BYTE, pixel);
    gl.bindFramebuffer(gl.FRAMEBUFFER, null);

    const id = (pixel[0] | (pixel[1] << 8) | (pixel[2] << 16)) - 1;
    this.selected = id >= 0 && id < this.faceCount ? id : -1;
    this.draw();
    if (this.onSelect) this.onSelect(this.selected);
  }

  // ---- drawing --------------------------------------------------------
  _resize() {
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    const w = Math.max(1, Math.round(this.canvas.clientWidth * dpr));
    const h = Math.max(1, Math.round(this.canvas.clientHeight * dpr));
    if (this.canvas.width !== w || this.canvas.height !== h) {
      this.canvas.width = w; this.canvas.height = h;
      this._sizePick(w, h);
    }
  }

  draw() {
    const gl = this.gl;
    gl.viewport(0, 0, this.canvas.width, this.canvas.height);
    gl.clearColor(0, 0, 0, 0);
    gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
    if (!this.vao) return;

    const {eye, view, proj} = this._camera();

    gl.useProgram(this.prog);
    gl.uniformMatrix4fv(gl.getUniformLocation(this.prog, 'uProj'), false, proj);
    gl.uniformMatrix4fv(gl.getUniformLocation(this.prog, 'uView'), false, view);
    gl.uniform3fv(gl.getUniformLocation(this.prog, 'uEye'), eye);
    gl.uniform1i(gl.getUniformLocation(this.prog, 'uSelected'), this.selected);
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D, this.colorTex);
    gl.uniform1i(gl.getUniformLocation(this.prog, 'uFaceColor'), 0);
    gl.bindVertexArray(this.vao);
    gl.drawArrays(gl.TRIANGLES, 0, this.triCount * 3);

    if (this.showStock && this.stockCount) {
      gl.useProgram(this.lineProg);
      gl.uniformMatrix4fv(gl.getUniformLocation(this.lineProg, 'uProj'), false, proj);
      gl.uniformMatrix4fv(gl.getUniformLocation(this.lineProg, 'uView'), false, view);
      gl.uniform4f(gl.getUniformLocation(this.lineProg, 'uColor'), 0.45, 0.52, 0.62, 0.85);
      gl.bindVertexArray(this.stockVao);
      gl.drawArrays(gl.LINES, 0, this.stockCount);
    }
    gl.bindVertexArray(null);
  }
}

// Cost heatmap: cool grey-blue for cheap faces through to hot amber-red.
export function heatColor(t) {
  const stops = [
    [0.00, [0.36, 0.44, 0.55]],
    [0.35, [0.20, 0.58, 0.72]],
