        assert deep.removal_depth_mm > shallow.removal_depth_mm
        assert deep.roughing_minutes / deep.area_mm2 > shallow.roughing_minutes / shallow.area_mm2


class TestOverrides:
    def test_suppressing_holes_removes_their_drilling(self, geometry):
        material = get_material("1.4301")
        holes = frozenset(f.index for f in geometry.faces if f.hole)
        reduced, params = apply_overrides(geometry, DesignOverrides(disabled_faces=holes))
        assert reduced.holes == []
        assert estimate_machining(reduced, material, params).drilling_minutes == 0

    def test_suppressing_holes_puts_the_metal_back(self, geometry):
        holes = frozenset(f.index for f in geometry.faces if f.hole)
        reduced, _ = apply_overrides(geometry, DesignOverrides(disabled_faces=holes))
        assert reduced.volume_mm3 > geometry.volume_mm3
        assert reduced.surface_area_mm2 < geometry.surface_area_mm2

    def test_suppressing_holes_lowers_the_price(self, geometry):
        holes = frozenset(f.index for f in geometry.faces if f.hole)
        base = run_quote(geometry=geometry, material_key="1.4301", quantity=25)
        cheaper = run_quote(
            geometry=geometry, material_key="1.4301", quantity=25,
            overrides=DesignOverrides(disabled_faces=holes),
        )
        assert cheaper.cost.unit_price_eur < base.cost.unit_price_eur

    def test_more_stock_allowance_costs_more(self, geometry):
        lean = run_quote(geometry=geometry, material_key="AW-6082",
                         overrides=DesignOverrides(stock_allowance_mm=1.0))
        fat = run_quote(geometry=geometry, material_key="AW-6082",
                        overrides=DesignOverrides(stock_allowance_mm=12.0))
        assert fat.cost.unit_price_eur > lean.cost.unit_price_eur
        assert fat.cost.stock_mass_kg > lean.cost.stock_mass_kg

    def test_empty_overrides_change_nothing(self, geometry):
        base = run_quote(geometry=geometry, material_key="AW-6082", quantity=10)
        same = run_quote(geometry=geometry, material_key="AW-6082", quantity=10,
                         overrides=DesignOverrides())
        assert same.cost.unit_price_eur == pytest.approx(base.cost.unit_price_eur)

    def test_run_quote_needs_a_part(self):
        with pytest.raises(ValueError, match="step_path or geometry"):
            run_quote(material_key="AW-6082")


