            part_mass_kg=1.65,
            quantity=25,
            target_price_eur=70.0,
            today=TODAY,
            **kwargs,
        )

    def test_simulated_round_never_dials(self, settings):
        rfq = self._create(replace(settings, rfq_simulate=True))
        assert rfq.simulated
        assert rfq.status == "complete"
        assert all(call.simulated and call.call_id is None for call in rfq.calls)
        assert all(call.quoted_price_eur > 0 for call in rfq.calls)

    def test_simulated_round_is_deterministic(self, settings):
        first = self._create(replace(settings, rfq_simulate=True))
        engine.reset()
        second = self._create(replace(settings, rfq_simulate=True))
        assert [c.quoted_price_eur for c in first.calls] == [
            c.quoted_price_eur for c in second.calls
        ]

    def test_missing_phone_numbers_block_rather_than_crash(self, settings):
        rfq = self._create(replace(settings, rfq_simulate=False, rfq_demo_phone=None))
        assert all(call.status == "blocked" for call in rfq.calls)
        assert all("suppliers.csv" in call.error for call in rfq.calls)
        assert rfq.status == "complete"

    def test_call_cap_is_enforced(self, settings):
        rfq = self._create(replace(settings, rfq_simulate=True, rfq_max_calls=2), limit=10)
        assert len(rfq.calls) == 2

    def test_best_quote_and_saving(self, settings):
        rfq = self._create(replace(settings, rfq_simulate=True))
        payload = rfq.to_dict()
        prices = [c.quoted_price_eur for c in rfq.calls]
        assert payload["best_price_eur"] == pytest.approx(round(min(prices), 2))
        assert payload["saving_total_eur"] == pytest.approx(
            payload["saving_per_part_eur"] * 25, rel=1e-6
        )

    def test_verdicts_score_against_the_model_price(self, settings):
        rfq = self._create(replace(settings, rfq_simulate=True))
        for call, row in zip(rfq.calls, rfq.to_dict()["calls"]):
            if call.quoted_price_eur < 70.0 * 0.95:
                assert row["verdict"] == "under"
            elif call.quoted_price_eur > 70.0 * 1.05:
                assert row["verdict"] == "over"
            else:
                assert row["verdict"] == "match"

    def test_group_with_no_history_is_refused(self, settings):
        with pytest.raises(engine.RfqError, match="Nobody to phone"):
            engine.create_rfq(
